const response = await fetch('http://localhost:8000/v1/skills/list');
const data = await response.json();
console.log(data);

const response = await fetch('http://localhost:8000/v1/skills/install', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ skill_uri: 'https://registry.cluaiz.com/skills/math-v1.zip' })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/skills/install")
    .json(&serde_json::json!({ "skill_uri": "https://registry.cluaiz.com/skills/math-v1.zip" }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

const response = await fetch('http://localhost:8000/v1/skills/remove', {
  method: 'DELETE',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ skill_id: 'skill_math' })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.delete("http://localhost:8000/v1/skills/remove")
    .json(&serde_json::json!({ "skill_id": "skill_math" }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);
